let ( let* ) = Result.bind

let parse s = match int_of_string_opt s with Some n -> Ok n | None -> Error ("bad int: " ^ s)
let positive n = if n > 0 then Ok n else Error ("not positive: " ^ string_of_int n)

let add_parsed a b =
  let* x = parse a in
  let* y = parse b in
  let* x = positive x in
  Ok (x + y)

let show = function Ok n -> string_of_int n | Error m -> m

let () = List.iter (fun (a, b) -> print_endline (show (add_parsed a b))) [("2", "3"); ("x", "3"); ("-1", "3")]

let parse s = match int_of_string_opt s with Some n -> Ok n | None -> Error s

let all_or_first_error xs =
  List.fold_left (fun acc s -> Result.bind acc (fun l -> Result.map (fun n -> n :: l) (parse s))) (Ok []) xs
  |> Result.map List.rev

let () =
  (match all_or_first_error ["1"; "2"; "3"] with Ok l -> Printf.printf "%d items\n" (List.length l) | Error e -> print_endline e);
  (match all_or_first_error ["1"; "b"; "c"] with Ok _ -> () | Error e -> Printf.printf "first error: %s\n" e);
  let oks, errors = List.partition_map (fun s -> match parse s with Ok n -> Left n | Error e -> Right e) ["1"; "b"; "3"; "d"] in
  Printf.printf "%d ok, errors: %s\n" (List.length oks) (String.concat "," errors)

